Source code in <code>packages/kcai-data-sampling-job/src/kcai_data_sampling_job/dataloaders/api/parquet.py</code> <pre><code>@override
def __iter__(self) -&gt; Iterator[Batch]:
    if self._parquet is None:
        return
    row_offset = 0
    for file in self._parquet.files:
        parquet_file = pq.ParquetFile(file)
        for batch in parquet_file.iter_batches(
            batch_size=self.load_batch_size,
            columns=self._read_columns(),
            use_threads=self.threads,
        ):
            if self.filter_expr is not None:
                batch = batch.filter(self.filter_expr)
            if len(batch) == 0:
                continue
            batch = self._apply_transforms(batch)
            yield self._decode_batch(batch, row_offset)
            row_offset += len(batch)
